#!/bin/bash
# Re-runs E4, E5, E6 and E8 and writes their logs (Windows runtimes here, WSL through wsl.exe).
R=/c/llvm-msil-scratch/p3/atomics-threads; T=$R/tools; W=/mnt/c/llvm-msil-scratch/p3/atomics-threads
wslrun() { MSYS_NO_PATHCONV=1 wsl -d Ubuntu -- bash $W/tools/wslrun.sh "$@"; }
winrun() { local exe=$1; echo "[net48] $(timeout 200 ./$exe 2>&1 | tr '\n' ' ')"; for v in 8 10; do echo "[net$v] $(timeout 200 dotnet exec --runtimeconfig $T/rc$v.json $exe 2>&1 | tr '\n' ' ')"; done; echo "[net8 TC=0] $(DOTNET_TieredCompilation=0 timeout 200 dotnet exec --runtimeconfig $T/rc8.json $exe 2>&1 | tr '\n' ' ')"; }
cd $R/e4-subword; { echo "# E4 subword CAS-loop test (sw), and the broken variant (swb: plain word store, negative control)"; for i in 1 2 3; do winrun sw.win.exe; wslrun $W/e4-subword sw.lnx.exe | tr '\n' ' '; echo; done; echo "## negative control"; winrun swb.win.exe; } > $R/logs/e4-subword.txt 2>&1
cd $R/e6-order; { echo "# E6a store buffering, 2,000,000 rounds: count of r0 == r1 == 0"; for v in sc relacq; do echo "## $v (win)"; winrun sb.$v.win.exe; done; echo "## WSL and native Linux"; MSYS_NO_PATHCONV=1 wsl -d Ubuntu -- bash $W/tools/wslsb.sh $W/e6-order; } > $R/logs/e6-sb.txt 2>&1
cd $R/e6-order; { echo "# E6b hoisting (hoist.il, hoist2.il): spin on a native-int address, flag set by another managed thread after 300 ms, join waits 3 s"; for f in hoist hoist2; do echo "## $f.exe"; echo "[net48]"; ./$f.exe; for v in 8 10; do for tc in 1 0; do echo "[net$v TieredCompilation=$tc]"; DOTNET_TieredCompilation=$tc dotnet exec --runtimeconfig $T/rc$v.json $f.exe; done; done; done; } > $R/logs/e6-hoist.txt 2>&1
cd $R/e6-order; { echo "# E6c barrier-spin.c through the prototype: WHICH 0 = plain int + asm volatile(\"\":::\"memory\") (D36 MEMBARRIER), 1 = volatile int, 2 = relaxed atomic; bs0fix = MEMBARRIER replaced by a call of a private noinlining empty method"; for w in 0 1 2; do echo "## WHICH=$w"; winrun bs$w.win.exe; done; echo "## bs0fix"; winrun bs0fix.win.exe; echo "## WSL"; MSYS_NO_PATHCONV=1 wsl -d Ubuntu -- bash $W/tools/wslbs.sh $W/e6-order; MSYS_NO_PATHCONV=1 wsl -d Ubuntu -- bash $W/tools/wslbs0.sh $W/e6-order; echo "## cost of a barrier in a loop of plain increments (cb.exe, ns per iteration)"; echo "[net48]"; ./cb/cb.exe | tail -3; for v in 8 10; do echo "[net$v TC=0]"; DOTNET_TieredCompilation=0 dotnet exec --runtimeconfig $T/rc$v.json cb/cb.exe | tail -3; done; } > $R/logs/e6-barrier.txt 2>&1
cd $R/e8-threads; { echo "# E8 counter.c (4 threads x 2,000,000 atomic_fetch_add + a racy plain counter), prototype build"; winrun counter.win.exe; wslrun $W/e8-threads counter.lnx.exe; echo "# texit.c (thread ends with ExitThread / pthread_exit)"; winrun texit.win.exe; wslrun $W/e8-threads texit.lnx.exe; echo "# c11thr.c (thrd_create, mtx_*, call_once)"; echo "[native win] $(./c11.native.exe | tr '\n' ' ')"; winrun c11.win.exe; wslrun $W/e8-threads c11.lnx.exe; echo "# exit while a created thread spins (texitrun)"; echo "[native win] $(timeout 60 ./texitrun.native.exe; echo rc=$?)"; winrun texitrun.win.exe; MSYS_NO_PATHCONV=1 wsl -d Ubuntu -- bash $W/tools/wsltc.sh $W/e8-threads; } > $R/logs/e8-threads.txt 2>&1
echo done
